import * as React from 'react';
import * as CssMasonryPrimitive from '@exhuma/core';
import { cn } from '@/lib/utils';

export interface CssMasonryProps extends React.ComponentPropsWithoutRef<typeof CssMasonryPrimitive.CssMasonry> {
  className?: string;
}

export const CssMasonry = React.forwardRef<HTMLDivElement, CssMasonryProps>(
  ({ className, children, ...props }, ref) => (
    <CssMasonryPrimitive.CssMasonry
      ref={ref}
      className={cn(
        'columns-1 sm:columns-2 md:columns-3 gap-4 [column-fill:_balance] w-full space-y-4',
        className
      )}
      {...props}
    >
      {children}
    </CssMasonryPrimitive.CssMasonry>
  )
);
CssMasonry.displayName = 'CssMasonry';

