import { Component, JSX, splitProps } from 'solid-js';
import * as CssMasonryPrimitive from '@exhuma/core';

export interface CssMasonryProps extends JSX.HTMLAttributes<HTMLDivElement> {
  [key: string]: unknown;
}

export const CssMasonry: Component<CssMasonryProps> = (props) => {
  const [local, others] = splitProps(props, ['class', 'children']);
  return (
    <CssMasonryPrimitive.CssMasonry
      class={`columns-1 sm:columns-2 md:columns-3 gap-4 [column-fill:_balance] w-full space-y-4 ${local.class ?? ''}`}
      {...others}
    >
      {local.children}
    </CssMasonryPrimitive.CssMasonry>
  );
};

