import { CssMasonry } from '@exhuma/core';

class ExhumaCssMasonryElement extends HTMLElement {
  connectedCallback() {
    this.classList.add('exhuma-css-masonry');
    this.style.display = 'block';
  }
}

if (!customElements.get('exhuma-css-masonry')) {
  customElements.define('exhuma-css-masonry', ExhumaCssMasonryElement);
}

react-native.code:
import React from 'react';
import { View, StyleSheet, type ViewProps } from 'react-native';
import * as CssMasonryPrimitive from '@exhuma/core';

export interface CssMasonryProps extends ViewProps {
  children?: React.ReactNode;
}

export function CssMasonry({ style, children, ...props }: CssMasonryProps) {
  return (
    <View style={[styles.container, style]} {...props}>
      {children}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: 16,
    borderWidth: 1,
    borderColor: '#e2e8f0',
    backgroundColor: '#ffffff',
    padding: 20,
    overflow: 'hidden',
  },
});

